	lines := make([]linePayload, 0, len(ret.Lines))
	for _, line := range ret.Lines {
		lines = append(lines, linePayload{SKU: line.SKU, Quantity: line.Quantity})
	}

	body, err := json.Marshal(returnPayload{OrderID: ret.OrderID, Lines: lines})
	if err != nil {
		return xerrors.Wrap(err, "encode request for inventory /stock/returns")
	}

	resp, err := http.Post(c.baseURL+"/stock/returns", "application/json", bytes.NewReader(body))
	if err != nil {
		return xerrors.Wrap(err, "call inventory /stock/returns")
	}
	defer func() {
		_ = resp.Body.Close()
	}()

	if resp.StatusCode >= 200 && resp.StatusCode < 300 {
		return nil
	}
	return responseError("/stock/returns", resp)
}

