// enter blocks until the order is free and answers with its release.
func (g *orderGate) enter(orderID string) func() {
	digest := fnv.New32a()
	_, _ = digest.Write([]byte(orderID))

	lock := &g.locks[int(digest.Sum32())%len(g.locks)]
	lock.Lock()
	return lock.Unlock
}

